from pathlib import Path
import re,json,html
B=Path(__file__).parent;D=B/'DX.8';F=D/'fragments';F.mkdir(exist_ok=True)
REF={x['id']:str(n+1) for n,x in enumerate(json.loads((D/'paquet.json').read_text())['passages'])}
def p(t,ids):
 refs=''.join('<sup class="r"><a href="#sb-'+i+'">'+REF.get(i,i)+'</a></sup>' for i in dict.fromkeys(ids.split()))
 ss=re.split(r'(?<=[.!?])\s+(?=[A-ZÀ-Ý«])',t);out=''
 for v in ss:
  z=v[-1] if v[-1:] in '.?!' else '.';v=v[:-1] if v[-1:] in '.?!' else v;out+=html.escape(v)+refs+z+' '
 return '<div class="p">'+out+'</div>\n'
def prose(t,ids):return ''.join(p(x.strip(),ids) for x in t.strip().split('\n') if x.strip())
def tab(h,rows):return '<div class="t" style="overflow-x:auto"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in h)+'</tr></thead><tbody>\n'+''.join('<tr>'+''.join('<td>'+p(c,refs)+'</td>' for c in cs)+'</tr>\n' for cs,refs in rows)+'</tbody></table></div>\n'
N={}
def w(n,title,t,ids):
 N[n]=N.get(n,0)+1;k=f'dx8-p{n}-w{N[n]}'
 return '<p><button class="w" popovertarget="'+k+'">'+html.escape(title)+'</button></p><div class="fenetre" popover id="'+k+'"><h4>'+html.escape(title)+'</h4>'+prose(t,ids)+'</div>\n'
def put(n,t):(F/f'p{n:02}.html').write_text(t)
put(1,prose('''La pseudopolyarthrite rhizomélique est une affection inflammatoire du sujet âgé qui associe des douleurs et une raideur des ceintures, particulièrement aux épaules, avec une limitation fonctionnelle.
Le nom international polymyalgia rheumatica est généralement abrégé PMR ; en français, PPR désigne la même entité. Le terme rhizomélique situe les plaintes vers la racine des membres.
La DGN décrit dans sa recommandation sur les myalgies une affection d’étiologie incertaine, touchant surtout les personnes âgées et plus souvent les femmes. Le tableau associe douleurs inflammatoires, raideur et limitation des régions cervicale, scapulaire et pelvienne.
Les recommandations EULAR intitulées 2025, publiées en juillet 2026, affirment que le diagnostic repose sur les signes, les symptômes et l’exclusion des affections qui les imitent. Elles précisent que les critères de classification ne doivent pas servir à poser le diagnostic.
Cette précision protège contre une assimilation fréquente : le patient ne devient pas atteint de PPR parce qu’il atteint un nombre de points. La démarche reste clinique et doit expliquer les manifestations observées.''','p8-dgn-clinique p83-eular26-diagnostic')+
tab(['Terme','Sens dans cette leçon','Conséquence pour le raisonnement'],[
(['La PPR est une maladie inflammatoire à phénotype proximal.','Les ceintures douloureuses et raides dominent la plainte.','L’évaluation cherche une constellation cohérente et les diagnostics concurrents.'],'p8-clinique p83-eular26-diagnostic'),
(['La myalgie désigne une sensation douloureuse musculaire.','La localisation ressentie ne prouve pas une lésion primitive de la fibre musculaire.','L’examen et les enzymes musculaires aident à distinguer douleur et myopathie.'],'p8-mecanisme p8-dd-myosite p8-dgn-ck'),
(['La raideur correspond à une difficulté à mobiliser après le repos.','Elle se manifeste notamment le matin dans les activités de la vie quotidienne.','Sa durée et son retentissement sont décrits au lieu d’être remplacés par le mot douleur.'],'p8-clinique p8-ch-clinique'),
(['L’ACG est une vascularite pouvant accompagner la PPR.','Les céphalées nouvelles, troubles visuels ou claudication mandibulaire changent l’urgence.','La forte suspicion d’ACG déclenche une prise en charge sans attendre la confirmation complète.'],'p8-acg p8-eular-r2')])+
w(1,'Pourquoi le préfixe pseudo ne signifie pas douleur imaginaire','''La dénomination historique ne remet pas en cause la réalité de l’inflammation ni du handicap. La douleur des ceintures s’accompagne de lésions synoviales et périarticulaires décrites en imagerie.
Une bursite sous-acromiale ou sous-deltoïdienne et une ténosynovite bicipitale peuvent contribuer aux symptômes des épaules.
Le cours distingue donc le vécu musculaire de la douleur et la localisation anatomique des anomalies inflammatoires, sans opposer symptômes authentiques et symptômes supposés.''','p8-mecanisme p8-imagerie')+
w(1,'PPR et artérite à cellules géantes : association sans identité','''La PPR peut précéder, accompagner ou suivre une artérite à cellules géantes. L’absence de plainte crânienne lors du premier examen ne dispense pas d’une nouvelle recherche lors du suivi.
La PPR isolée n’a pas la même urgence ischémique qu’une ACG fortement suspectée. EULAR conseille en général de confirmer la première avant d’introduire les glucocorticoïdes.
À l’inverse, une forte suspicion d’ACG demande des glucocorticoïdes sans délai pendant l’organisation des examens confirmatoires.''','p8-acg p8-eular-r2')+
prose('''La revue européenne de Lundberg et collaborateurs souligne qu’aucun examen isolé ne constitue un gold standard de PPR. Il n’existe pas de sérologie spécifique permettant de remplacer la synthèse clinique.
La réponse rapide aux glucocorticoïdes est historiquement caractéristique, mais elle ne démontre pas à elle seule cette maladie. Plusieurs affections concurrentes peuvent aussi s’améliorer sous corticoïdes.
EULAR déconseille désormais l’essai diagnostique de glucocorticoïdes avant l’évaluation spécialisée d’une PPR suspectée. L’amélioration après une prescription ne doit pas effacer les éléments qui manquaient au diagnostic initial.''','p8-diagnostic p8-dd-pr p8-eular-no-test'))
put(2,prose('''En Suisse, mediX fournit un cadre clinique de soins primaires, mais les documents suisses acquis ne contiennent pas de mesure nationale exploitable de l’incidence ou de la prévalence de PPR.
Cette absence ne permet pas de recopier un chiffre scandinave comme une statistique suisse. Les estimations européennes doivent rester attachées à l’âge et au territoire étudiés.
La revue de Lundberg et collaborateurs décrit une incidence augmentant avec l’âge et une maladie rarement observée avant cinquante ans. Les femmes sont environ deux à trois fois plus souvent atteintes que les hommes dans les données qu’elle synthétise.
La distribution géographique varie nettement. Les populations du nord de l’Europe présentent des incidences plus élevées que celles du sud dans les études citées, sans que cette observation détermine le diagnostic d’un individu.''','p8-epi p8-ch-clinique')+
tab(['Estimation rapportée','Population et provenance','Ce qui peut en être conclu'],[
(['L’incidence suédoise est rapportée entre 34 et 50 pour 100 000.','La revue européenne publiée en 2022 rapporte cette plage pour les personnes d’au moins cinquante ans.','La valeur décrit les études suédoises reprises ; elle ne représente pas la population suisse.'],'p8-epi'),
(['Une incidence de 113 pour 100 000 par année est citée en Norvège.','Le dénominateur comprend les personnes d’au moins cinquante ans dans l’étude citée.','Le contexte nord-européen illustre l’hétérogénéité des estimations.'],'p8-epi'),
(['Une incidence de 13 pour 100 000 par année est citée en Italie.','La même revue rapporte cette mesure pour une population d’au moins cinquante ans.','Elle ne doit pas être combinée avec la mesure norvégienne pour produire une moyenne non calculée.'],'p8-epi'),
(['Les femmes sont environ deux à trois fois plus touchées.','Il s’agit de la synthèse des données épidémiologiques de la revue.','Le sexe module le contexte, mais un homme avec tableau compatible nécessite la même démarche diagnostique.'],'p8-epi')])+
w(2,'Ne pas inverser le sens d’une association','''La revue rapporte que des symptômes de PPR sont présents chez environ la moitié des patients ayant une ACG.
Cette proportion décrit les personnes déjà atteintes d’ACG. Elle ne signifie pas que la moitié de tous les patients avec PPR ont une artérite démontrée.
Les estimations de vascularite subclinique dépendent des populations et des méthodes de détection. L’évaluation individuelle repose sur les manifestations, l’examen et la stratégie spécialisée.''','p8-acg p8-epi p8-eular-r1')+
prose('''Le début peut être relativement rapide, avec un tableau constitué en quelques jours à quelques semaines. Une installation plus insidieuse peut d’abord évoquer une autre cause de fatigue, d’amaigrissement ou de douleurs.
La restriction des gestes matinaux touche l’habillage, le lever et les soins personnels. La charge de maladie ne se limite donc pas au nombre d’articulations douloureuses.
L’évolution peut comporter des rechutes et une exposition prolongée aux glucocorticoïdes. Le nouvel objectif EULAR est une rémission permettant d’arrêter les glucocorticoïdes, plutôt qu’un traitement maintenu indéfiniment par habitude.
Le suivi doit aussi tenir compte des infections, de la fragilité osseuse, des complications métaboliques et oculaires liées au traitement. Ces risques prennent une importance particulière dans une population souvent âgée.''','p8-clinique p8-eular-r3 aips-p8-prednisone_galepharm-6')+
w(2,'Mortalité : éviter une certitude excessive','''La revue européenne compare des travaux aux résultats hétérogènes sur la mortalité. Elle rapporte qu’une grande étude n’a pas identifié d’effet significatif du diagnostic de PPR sur l’espérance de vie.
Certains travaux retrouvent des résultats différents et peuvent mêler PPR et ACG ou subir un biais de surveillance. La revue ne permet donc pas d’annoncer un taux suisse spécifique.
L’absence de surmortalité clairement établie pour la PPR isolée ne supprime ni l’urgence d’une ACG associée ni les risques d’une corticothérapie mal surveillée.''','p8-mortalite p8-eular-r2 aips-p8-prednisone_galepharm-6'))
put(3,prose('''L’origine de la PPR demeure incomplètement expliquée. Les données soutiennent une interaction de l’immunité innée et adaptative, dans un contexte de vieillissement immunitaire, plutôt qu’une cause unique démontrée.
Les biopsies synoviales décrites dans la revue européenne montrent une synovite avec infiltration leucocytaire et prolifération vasculaire. Les macrophages et lymphocytes T mémoires y sont particulièrement représentés.
L’activation endothéliale et l’expression de molécules d’adhésion peuvent faciliter le recrutement cellulaire. Ces observations relient l’amorce immunitaire à la constitution d’une inflammation locale.
La signalisation de l’IL-6 participe au tableau systémique et à la réaction inflammatoire biologique. Il ne s’agit toutefois pas d’un autoanticorps spécifique pouvant identifier la PPR chez une personne donnée.
À l’échelle tissulaire, la synovite, les bursites et la ténosynovite expliquent une partie de la douleur et de la raideur des ceintures. L’échographie peut montrer ces anomalies, tandis que la biologie mesure le retentissement inflammatoire.
Le passage de l’inflammation aux difficultés fonctionnelles se manifeste lors du lever, de l’habillage ou des mouvements d’élévation des bras. L’examen relie ces plaintes à la mobilité et à la douleur, au lieu de déduire une paralysie du seul récit de faiblesse.''','p8-mecanisme p8-cellules p8-clinique p8-imagerie')+
tab(['Échelon perturbé','Manifestation et exploration','Lien thérapeutique'],[
(['L’activation immunitaire et la signalisation cytokinaire entretiennent l’inflammation.','La CRP et la VS témoignent d’une réaction inflammatoire mais ne sont pas spécifiques.','Les glucocorticoïdes ont une action anti-inflammatoire ; le bénéfice doit être confronté à leurs effets systémiques.'],'p8-mecanisme p8-bio aips-p8-prednisone_galepharm-12'),
(['L’inflammation synoviale et périarticulaire touche les ceintures.','L’échographie recherche bursite, ténosynovite et synovite aux sites pertinents.','La diminution de l’activité inflammatoire doit se traduire par une amélioration des symptômes et de la fonction.'],'p8-imagerie p8-eular-r12'),
(['La douleur limite le mouvement sans imposer une destruction musculaire.','L’examen compare gêne, mobilité et force ; les CK sont typiquement normales dans la PPR.','Une faiblesse vraie ou une anomalie musculaire impose de reconsidérer le diagnostic.'],'p8-diagnostic p8-dgn-ck p8-dd-myosite'),
(['La voie IL-6 constitue une cible pour certaines formes sélectionnées.','Les marqueurs inflammatoires peuvent être atténués sous blocage de cette voie.','EULAR discute des anti-IL-6R dans des situations spécialisées ; l’autorisation suisse doit être vérifiée séparément.'],'p8-eular-r6 p8-eular-rechute aips-p8-kevzara-3 aips-p8-kevzara-6')])+
w(3,'Une douleur dite musculaire peut venir des tissus périarticulaires','''L’échographie met fréquemment en évidence des bourses inflammatoires autour de l’épaule et une atteinte de la gaine du long biceps.
Ces structures interviennent dans le glissement et le mouvement. Leur inflammation peut produire des douleurs ressenties dans la région proximale du membre.
L’absence habituelle d’élévation des CK et l’absence de faiblesse musculaire primitive aident à distinguer ce tableau d’une myosite inflammatoire.''','p8-mecanisme p8-imagerie p8-dgn-ck p8-dd-myosite')+
w(3,'Comment la prednisone agit et pourquoi sa toxicité compte','''La prednisone exerce son activité sous forme de prednisolone. La notice explique que ses effets passent par la stimulation de la synthèse de protéines spécifiques, avec une action au niveau du noyau cellulaire.
Le même médicament possède des effets anti-inflammatoires et immunosuppresseurs, mais aussi métaboliques, cataboliques et minéralocorticoïdes.
Le choix de la dose minimale efficace, la diminution progressive et la surveillance répondent à ce mécanisme général. Une amélioration de la PPR ne signifie pas que le traitement devient sans risque.''','aips-p8-prednisone_galepharm-12 aips-p8-prednisone_galepharm-4 aips-p8-prednisone_galepharm-6')+
prose('''Le maintien de symptômes peut refléter une activité inflammatoire persistante, une rechute, une autre maladie ou un effet du traitement. EULAR demande une nouvelle évaluation diagnostique lorsque la maladie paraît réfractaire.
L’insuffisance surrénalienne peut produire des symptômes généraux lors de la diminution des glucocorticoïdes. Elle figure parmi les explications à ne pas confondre avec une rechute automatique.
La coexistence d’une vascularite change la chaîne de risque : l’inflammation artérielle peut menacer la perfusion et la vision. Les signes crâniens ou visuels doivent donc être recherchés indépendamment de l’intensité des douleurs d’épaule.
Les hypothèses concernant un facteur déclenchant environnemental ne justifient pas de présenter la PPR comme une infection contagieuse ni de lui attribuer une prévention étiologique démontrée.''','p8-eular-r10 p8-eular-rechute p8-acg p8-cellules'))
put(4,prose('''🚩 E2 conditionnel — Avant de retenir une PPR isolée, rechercher une artérite à cellules géantes associée. Une céphalée nouvelle, une douleur de mâchoire à la mastication ou une manifestation visuelle changent la priorité.
EULAR demande une orientation spécialisée pour toute suspicion de PPR ou d’ACG, avec un recours urgent pour cette dernière. Le développement de la recommandation situe l’évaluation d’une ACG suspectée dans les vingt-quatre heures, et immédiatement en présence de manifestations crâniennes préoccupantes.
La forte suspicion clinique d’ACG justifie l’introduction des glucocorticoïdes sans attendre les résultats confirmatoires. La PPR sans menace vasculaire suit au contraire une démarche de confirmation avant traitement dans la plupart des situations.
Ce badge E2 reprend la menace conditionnelle de la liste canonique. Il n’autorise aucun délai d’attente chez une personne menacée de perte visuelle.
Après l’exclusion de cette urgence, la démarche compare la PPR aux affections qui produisent des douleurs proximales chez une personne plus âgée. Une réponse aux corticoïdes ne tranche pas suffisamment cette comparaison.''','p83-eular26-orientation p8-eular-r2 p8-dd-pr')+
tab(['Hypothèse','Élément qui discrimine','Piège fréquent','Décision si l’hypothèse devient probable'],[
(['L’ACG associée peut menacer la vision.','La céphalée récente, la claudication mandibulaire et les troubles visuels conduisent à une évaluation vasculaire spécialisée.','Une amélioration des épaules ne prouve pas que le risque artériel a disparu.','Organiser l’avis urgent et traiter sans retard si la suspicion est forte.'],'p8-acg p8-eular-r2'),
(['Une polyarthrite rhumatoïde tardive peut débuter aux épaules.','Une synovite symétrique des petites articulations et des anticorps RF/ACPA positifs favorisent cette hypothèse.','La forme séronégative et la réponse commune aux corticoïdes peuvent entretenir la confusion.','Reprendre l’examen articulaire et la stratégie rhumatologique plutôt que maintenir par défaut le diagnostic de PPR.'],'p8-dd-pr'),
(['Une myosite inflammatoire affecte la force proximale.','Une faiblesse objective, des CK élevées ou des manifestations extramusculaires orientent vers une myopathie.','Le mot faiblesse employé par le patient peut seulement décrire la douleur ; il faut l’examiner.','Organiser le bilan musculaire et d’organes approprié, particulièrement en cas de dysphagie.'],'p8-dd-myosite p8-dgn-ck'),
(['Une néoplasie ou une autre affection générale peut imiter le tableau.','Un profil atypique, une évolution inhabituelle ou une résistance au traitement imposent une réévaluation.','L’amaigrissement n’est pas spécifique et ne prouve ni une PPR ni un cancer.','Choisir les examens orientés par l’histoire et l’examen, avec recours spécialisé.'],'p8-dd-cancer p8-eular-r10')])+
w(4,'Une PPR apparente avec faiblesse objective demande une autre branche','''Le patient peut limiter l’effort parce que le mouvement fait mal. Le médecin distingue ce comportement d’une diminution reproductible de la force.
La revue clinique décrit une mobilité douloureusement limitée dans la PPR, habituellement sans atrophie ni faiblesse primitive. Une faiblesse véritable ou une dysphagie fait rechercher une myosite ou une autre affection neuromusculaire.
Les CK contribuent à cette distinction, mais un résultat doit rester interprété avec la clinique et les traitements déjà reçus.''','p8-diagnostic p8-dd-myosite p8-dgn-ck')+
w(4,'Hypothyroïdie, arthrose et syndrome douloureux diffus','''Une hypothyroïdie peut produire des douleurs diffuses et une fatigue ; le bilan thyroïdien répond alors à une hypothèse clinique concurrente.
L’arthrose des hanches ou une atteinte cervicale dégénérative peuvent provoquer douleurs et raideur. L’absence de syndrome inflammatoire et la distribution mécanique orientent, sans transformer une radiographie dégénérative en explication obligatoire de toute plainte.
Une fibromyalgie se situe dans un autre cadre clinique et ne justifie pas une corticothérapie destinée à une PPR non démontrée.''','p8-dd-autres p8-dd-fibro')+
prose('''La recherche de diagnostic concurrent se poursuit au cours du temps. Une nouvelle synovite périphérique, un résultat biologique inhabituel ou un besoin de traitement difficile à expliquer peuvent modifier la conclusion initiale.
EULAR définit la réévaluation comme une étape nécessaire devant une maladie réfractaire. Elle peut conduire à un centre spécialisé et à une exploration ciblée d’autres maladies rhumatismales, de néoplasies ou de vasculopathies.
L’augmentation des glucocorticoïdes ne constitue pas une réponse automatique à chaque douleur réapparue. La cause de la plainte et la possibilité d’une insuffisance surrénalienne doivent être prises en compte.''','p8-eular-r10 p8-eular-rechute'))
put(5,prose('''L’entretien précise d’abord la chronologie des douleurs et de la raideur. Le médecin demande comment le patient se lève, se retourne dans son lit, s’habille ou élève les bras le matin.
La durée de la raideur après le réveil doit être décrite avec les mots du patient, puis estimée en minutes. La raideur prolongée constitue un élément du phénotype inflammatoire, sans être une preuve isolée de PPR.
Le siège des plaintes est cartographié : cou, épaules, bras, bassin, hanches et cuisses. Une plainte d’abord unilatérale peut devenir bilatérale selon la description suisse mediX.
La relation au repos et au mouvement aide à caractériser l’inflammation. mediX décrit une aggravation après repos et une amélioration lors de la mobilisation.
L’anamnèse demande systématiquement une céphalée nouvelle, une douleur à la mastication, une sensibilité du cuir chevelu et une modification de la vision. Ces questions sont posées même si le motif annoncé reste une douleur de ceinture.
Les symptômes généraux comprennent fatigue, perte d’appétit, amaigrissement et fièvre éventuelle. Leur présence peut accompagner la PPR mais oblige aussi à examiner les diagnostics concurrents.''','p8-clinique p8-ch-clinique p8-ch-acg p8-acg')+
tab(['Question','Lien avec le mécanisme ou le risque','Utilisation de la réponse'],[
(['Le matin, quels gestes sont impossibles ou beaucoup plus lents ?','L’inflammation périarticulaire et la raideur perturbent les activités proximales.','Choisir des repères fonctionnels individuels pour l’examen et le suivi.'],'p8-clinique p8-mecanisme'),
(['La gêne est-elle surtout une douleur, une raideur ou une perte de force ?','La PPR limite la fonction sans présenter habituellement une faiblesse musculaire primitive.','Orienter l’examen actif, passif et musculaire pour éviter la confusion avec une myosite.'],'p8-diagnostic p8-dd-myosite'),
(['La mâchoire devient-elle douloureuse pendant la mastication ?','Une claudication mandibulaire peut signaler une atteinte artérielle.','Ouvrir sans retard la branche ACG et préciser les manifestations associées.'],'p8-ch-acg p8-eular-r2'),
(['Une vision double, une perte visuelle transitoire ou persistante est-elle apparue ?','La menace ischémique peut devenir irréversible.','Organiser immédiatement l’évaluation adaptée à la suspicion d’ACG.'],'p8-ch-acg p83-eular26-orientation'),
(['Quels glucocorticoïdes ou immunomodulateurs ont déjà été utilisés ?','Un traitement peut modifier les signes et les marqueurs, compliquant la confirmation.','Documenter produit, dose et durée avant d’interpréter l’examen.'],'p8-eular-no-test aips-p8-prednisone_galepharm-6')])+
tab(['Drapeau rouge','Interprétation','Conduite'],[
(['🚩 Une plainte visuelle nouvelle accompagne le tableau.','Une ACG doit être envisagée, y compris si les épaules semblent déjà soulagées.','Avis spécialisé immédiat et glucocorticoïdes sans attendre la confirmation si la suspicion est forte.'],'p8-acg p8-eular-r2'),
(['🚩 Une céphalée récente s’associe à une claudication mandibulaire ou une sensibilité temporale.','L’ensemble renforce la suspicion de vascularite crânienne.','Organiser le parcours rapide d’ACG et les examens sans retarder le traitement nécessaire.'],'p83-eular26-signes-urgence p83-eular23-imagerie-urgente'),
(['🚩 Une faiblesse véritable ou une dysphagie domine.','Une myopathie inflammatoire ou une autre affection peut expliquer mieux la présentation.','Évaluer la fonction et les atteintes d’organes, puis orienter le bilan spécialisé.'],'p8-dd-myosite'),
(['🚩 Des symptômes persistent malgré une prise en charge appropriée.','La réfractarité peut traduire une erreur diagnostique ou un diagnostic associé.','Réexaminer la conclusion avant toute escalade prolongée.'],'p8-eular-r10')])+
w(5,'Interroger le terrain avant une corticothérapie prolongée','''Le bilan initial recherche notamment diabète, hypertension, maladie cardiovasculaire, fragilité osseuse, antécédent ulcéreux, infection, glaucome ou cataracte.
La notice demande une prudence particulière dans de nombreuses situations, dont l’insuffisance rénale, les antécédents psychiatriques et les infections latentes.
Ces informations influencent la stratégie de dose, la surveillance et la discussion d’un traitement d’épargne. Elles ne sont pas reportées à une consultation ultérieure lorsque le traitement a déjà commencé.''','aips-p8-prednisone_galepharm-6 p8-ch-prevention')+
w(5,'La chronologie médicamenteuse évite plusieurs erreurs','''Le médecin recherche une exposition récente ou actuelle à des corticoïdes, car elle peut atténuer le tableau et rendre l’évaluation plus difficile.
Les interactions potentielles comprennent les inhibiteurs puissants du CYP3A4, les antidiabétiques, les anticoagulants, les diurétiques et les anti-inflammatoires non stéroïdiens.
Les décisions se prennent sur la liste réelle des produits, y compris ceux prescrits par d’autres médecins. Une plainte nouvelle sous traitement peut être liée à un effet indésirable plutôt qu’à une activité persistante de PPR.''','p8-eular-no-test aips-p8-prednisone_galepharm-7')+
prose('''La discussion aborde également l’autonomie et l’environnement. Une limitation des épaules peut rendre l’habillage, les repas ou les soins personnels difficiles, même si le patient minimise la douleur en consultation.
Le médecin choisit avec lui des activités concrètes à suivre. Leur amélioration apporte une information distincte de la baisse d’un marqueur biologique.
L’annonce d’une maladie inflammatoire et d’une corticothérapie peut susciter une inquiétude importante. EULAR recommande une décision partagée et une information sur les manifestations d’alarme et les risques du traitement.''','p8-clinique p83-eular26-diagnostic p8-eular-r12'))
put(6,prose('''L’examen commence par le repère fonctionnel habituel du patient : se lever, marcher, porter les mains vers la tête et mobiliser les épaules sans raideur prolongée ni douleur empêchant le geste.
La normalité attendue n’est pas un angle articulaire unique applicable à toutes les personnes âgées. L’évaluation compare les côtés, les gestes actifs et la mobilisation réalisée par l’examinateur, en tenant compte des limitations préexistantes.
Le clinicien demande une élévation active des bras et observe l’amplitude, la douleur et les compensations. Il complète ensuite par une mobilisation douce pour déterminer ce qui relève de la douleur et ce qui évoque une restriction structurelle.
La palpation des régions scapulaires et des cuisses peut être sensible. La revue européenne décrit une douleur à la palpation profonde et une mobilité des épaules restreinte, sans atrophie ni faiblesse musculaire habituelle.
La force doit être appréciée en tenant compte de la douleur. Une contraction limitée parce qu’elle déclenche la plainte ne peut pas être assimilée sans examen à une faiblesse primitive.
L’examen articulaire ne se limite pas aux épaules : poignets, mains et genoux peuvent révéler une synovite et orienter vers une polyarthrite tardive ou un autre diagnostic.''','p8-diagnostic p8-dd-pr p8-dd-myosite')+
tab(['Examen','Technique clinique','Résultat utile et piège'],[
(['L’élévation active des bras évalue le retentissement scapulaire.','Le patient exécute le mouvement pendant que l’examinateur observe les deux côtés et demande où apparaît la douleur.','Une limitation douloureuse est compatible avec le tableau, mais elle n’est pas spécifique de PPR.'],'p8-clinique p8-diagnostic'),
(['La mobilisation complémentaire explore la restriction.','Le clinicien accompagne doucement le mouvement et compare avec l’exécution active, sans forcer une zone douloureuse.','Une gêne articulaire ou périarticulaire doit être rapprochée de l’imagerie et des autres diagnostics.'],'p8-diagnostic p8-imagerie'),
(['L’évaluation de force recherche une véritable atteinte musculaire.','Le mouvement et la résistance sont appréciés dans des conditions où la douleur est identifiée.','Un déficit objectif, une atrophie ou une dysphagie orientent hors de la PPR simple.'],'p8-diagnostic p8-dd-myosite'),
(['L’examen des petites articulations recherche une synovite.','Les articulations symptomatiques sont inspectées et palpées, avec comparaison des côtés.','Une atteinte symétrique des petites articulations favorise une polyarthrite rhumatoïde, même séronégative.'],'p8-dd-pr'),
(['L’examen crânien et vasculaire recherche une ACG.','Le clinicien examine les régions temporales et confronte douleur, épaississement ou sensibilité aux symptômes visuels et masticatoires.','Un examen peu contributif ne suffit pas à éliminer une vascularite ; le parcours spécialisé reste fondé sur la suspicion globale.'],'p8-ch-acg p83-eular26-signes-urgence p83-eular23-probabilite')])+
w(6,'La force préservée aide à distinguer douleur et myosite','''La PPR produit principalement des douleurs et une raideur. La revue clinique ne décrit pas une faiblesse primitive comme caractéristique de l’affection.
Le médecin recherche donc une contraction effective malgré la gêne et vérifie si la limitation disparaît dans une autre position moins douloureuse.
Lorsque la force est réellement diminuée, le raisonnement se réoriente vers les myopathies ou d’autres affections ; les CK et le bilan spécialisé sont alors choisis pour cette question.''','p8-diagnostic p8-dd-myosite p8-dgn-ck')+
w(6,'Examen temporal : ce qu’il peut apporter','''La sensibilité du cuir chevelu et une artère temporale épaissie ou douloureuse font partie des signes rapportés par mediX et EULAR pour l’ACG.
L’examinateur décrit ce qu’il observe et palpe plutôt que de remplacer l’ensemble par une formule binaire. Les symptômes visuels et la claudication mandibulaire restent déterminants même si la palpation est peu marquée.
L’échographie spécialisée recherche ensuite des anomalies pariétales selon le parcours EULAR. La palpation ne constitue pas un substitut à cette confirmation.''','p8-ch-acg p83-eular26-signes-urgence p83-eular23-echo')+
prose('''Les données de l’examen sont rapprochées de l’état général, du poids et des manifestations systémiques. Une anomalie inexpliquée ne doit pas être absorbée artificiellement dans le diagnostic de PPR.
Un examen initial réalisé avant glucocorticoïdes est particulièrement informatif. Le traitement peut réduire rapidement les manifestations et compliquer ensuite l’interprétation des tests.
Au suivi, les mêmes gestes fonctionnels sont repris pour apprécier un changement concret. L’examen cherche aussi une complication du traitement, notamment une faiblesse nouvelle, un changement visuel ou une manifestation infectieuse.
Aucune sensibilité ou spécificité inventée n’est attribuée à un geste isolé d’épaule. La valeur de l’examen réside dans sa cohérence avec la chronologie, la biologie et les diagnostics concurrents.''','p8-diagnostic p8-eular-no-test p8-eular-r12 aips-p8-prednisone_galepharm-6'))
put(7,prose('''Point 7.1 — Le syndrome inflammatoire des ceintures réunit des douleurs proximales, une raideur matinale et une limitation des gestes. Les signes fonctionnels sont décrits par le patient ; les signes physiques montrent une mobilité douloureuse et parfois une sensibilité régionale.
Point 7.2 — Le syndrome général inflammatoire associe fatigue, diminution de l’appétit, perte de poids ou fièvre. Les marqueurs inflammatoires peuvent soutenir ce regroupement, sans en désigner la cause.
Point 7.3 — Le syndrome évocateur d’ACG associe selon le patient céphalée nouvelle, claudication mandibulaire, sensibilité du cuir chevelu et manifestations visuelles. Il ouvre la branche urgente et peut apparaître à distance du diagnostic initial de PPR.
Point 7.4 — Le syndrome myopathique concurrent se caractérise surtout par une faiblesse objective, éventuellement accompagnée d’anomalies enzymatiques ou d’une atteinte extramusculaire. Il ne doit pas être confondu avec la difficulté à bouger à cause de la douleur.
Ces regroupements structurent l’analyse du cas. Leur intitulé n’est pas un diagnostic automatique et leur présence simultanée peut indiquer une maladie associée.''','p8-clinique p8-ch-clinique p8-acg p8-dd-myosite')+
tab(['Syndrome','Signes fonctionnels','Signes physiques ou biologiques'],[
(['Le tableau des ceintures est dominé par la raideur et la douleur.','Les gestes matinaux, l’habillage et les mouvements au lit deviennent difficiles.','La mobilité est limitée par la douleur ; une atrophie ou une faiblesse primitive n’est pas habituelle.'],'p8-clinique p8-diagnostic'),
(['Le tableau systémique traduit une inflammation possible.','Le patient décrit fatigue, anorexie, fièvre éventuelle ou amaigrissement.','Les marqueurs inflammatoires et parfois la numération montrent des anomalies non spécifiques.'],'p8-ch-clinique p8-bio'),
(['Le tableau vasculaire crânien est une menace conditionnelle.','Les céphalées, troubles visuels ou douleurs à la mastication sont recherchés activement.','Une sensibilité ou un épaississement temporal peut renforcer la suspicion, sans être indispensable.'],'p8-ch-acg p83-eular26-signes-urgence'),
(['Le tableau musculaire déficitaire fait rechercher une autre affection.','Une difficulté à avaler ou une perte de force prédominante est inhabituelle pour une PPR isolée.','La faiblesse objective et les CK orientent le bilan neuromusculaire.'],'p8-dd-myosite p8-dgn-ck')])+
w(7,'Raideur matinale : définition, recherche et mécanisme','''La raideur désigne une difficulté à initier ou réaliser les mouvements après une période d’immobilité. Le patient la distingue de l’intensité douloureuse proprement dite.
Le médecin demande combien de temps les gestes restent difficiles après le lever et quelles activités s’améliorent ensuite. L’inflammation synoviale et périarticulaire explique une partie de ce retentissement.
La durée supérieure à 45 minutes intervient dans les critères de classification de 2012 ; elle ne constitue pas, à elle seule, une preuve diagnostique.''','p8-clinique p8-mecanisme p8-classification')+
w(7,'Claudication mandibulaire : rechercher un symptôme d’effort','''Le terme décrit une douleur ou une gêne de la mâchoire provoquée par la mastication. Le médecin demande si la plainte apparaît pendant cet effort plutôt que de se limiter à « avez-vous mal aux dents ? ».
Dans le contexte de PPR, ce symptôme peut évoquer une atteinte artérielle et renforcer la suspicion d’ACG.
Il entraîne une démarche urgente, particulièrement lorsqu’il accompagne une céphalée nouvelle ou un trouble visuel.''','p8-ch-acg p83-eular26-signes-urgence')+
w(7,'Manifestation visuelle : préciser sans attendre','''Le patient doit décrire une baisse de vision, une perte transitoire ou une vision double, ainsi que leur début et leur évolution.
Ces symptômes sont recherchés explicitement car la plainte initiale peut rester centrée sur les épaules. Une menace ischémique impose de changer immédiatement la priorité.
L’évaluation spécialisée ne doit pas être différée pour compléter tranquillement un score de PPR.''','p8-ch-acg p83-eular26-orientation p8-eular-r2')+
w(7,'Synovite : un signe qui garde plusieurs causes possibles','''La synovite désigne l’inflammation de la membrane synoviale d’une articulation. Elle peut contribuer à une tuméfaction, à la douleur et à une limitation de mobilité.
Le médecin cherche les articulations périphériques concernées et leur répartition. Une distribution symétrique des petites articulations oriente particulièrement vers une polyarthrite rhumatoïde.
L’échographie peut montrer une synovite mais ce constat n’est pas spécifique de PPR ; il doit être intégré à la distribution clinique et biologique.''','p8-diagnostic p8-dd-pr p8-imagerie')+
w(7,'Bursite et ténosynovite : deux tissus périarticulaires distincts','''La bursite correspond à l’inflammation d’une bourse de glissement. La ténosynovite concerne la gaine d’un tendon.
Dans la PPR, l’échographie recherche notamment les bourses sous-acromiale et sous-deltoïdienne ainsi que la gaine du long biceps.
Ces constatations rendent cohérente une douleur régionale proximale, mais ne dispensent pas d’exclure une affection concurrente.''','p8-mecanisme p8-imagerie')+
prose('''La dissociation entre douleur et déficit doit être réévaluée au cours du traitement. Une nouvelle faiblesse peut relever d’une autre maladie ou d’un effet indésirable, alors même que l’inflammation initiale diminue.
Les symptômes généraux à la réduction des glucocorticoïdes ne prouvent pas tous une rechute. EULAR rappelle le rôle possible d’une insuffisance surrénalienne et demande une analyse clinique rigoureuse.
Le suivi revient ainsi aux signes observables et à leur mécanisme, au lieu de transformer chaque plainte en justification d’une dose supplémentaire.''','p8-eular-rechute aips-p8-prednisone_galepharm-6'))
put(8,prose('''Le diagnostic positif de PPR repose sur une présentation clinique compatible et sur l’absence d’une meilleure explication. EULAR rappelle expressément l’absence de test diagnostique unique.
Les critères provisoires EULAR/ACR de 2012 sont présentés parce qu’ils sont utiles à connaître pour l’examen fédéral et les études. Ils ne doivent pas être rebaptisés critères diagnostiques.
Leur population d’entrée comprend les personnes d’au moins 50 ans avec douleurs bilatérales des épaules et CRP ou VS anormale, sans autre pathologie expliquant mieux le tableau.
Le score clinique attribue des points à la raideur matinale, à l’atteinte de hanche, à l’absence de RF ou ACPA et à l’absence d’autre douleur articulaire. L’échographie ajoute deux items possibles.
La présence de signes atypiques, de marqueurs normaux ou d’une autre maladie plausible exige un raisonnement spécialisé, même si certains items sont présents.''','p83-eular26-diagnostic p8-classification p8-score-table')+
tab(['Critère du score provisoire','Points sans échographie','Points avec échographie'],[
(['La raideur matinale dure plus de 45 minutes.','Le score attribue 2 points.','Le score conserve 2 points.'],'p8-score-table'),
(['Une douleur de hanche ou une limitation de mobilité de hanche est présente.','Le score attribue 1 point.','Le score conserve 1 point.'],'p8-score-table'),
(['Le RF ou les ACPA sont absents selon le libellé original.','Le score attribue 2 points.','Le score conserve 2 points.'],'p8-score-table'),
(['Il n’existe pas d’autre douleur articulaire.','Le score attribue 1 point.','Le score conserve 1 point.'],'p8-score-table'),
(['Au moins une épaule présente une bursite sous-deltoïdienne, une ténosynovite bicipitale ou une synovite glénohumérale, avec au moins une hanche présentant une synovite ou une bursite trochantérienne.','Cet item ne participe pas au score sans échographie.','L’association échographique attribue 1 point.'],'p8-score-table'),
(['Les deux épaules présentent une bursite sous-deltoïdienne, une ténosynovite bicipitale ou une synovite glénohumérale.','Cet item ne participe pas au score sans échographie.','L’atteinte bilatérale attribue 1 point.'],'p8-score-table')])+
prose('''Le seuil de classification est d’au moins 4 points sans échographie et d’au moins 5 points avec échographie. Ces seuils s’utilisent seulement après vérification de la population d’entrée.
Dans l’étude de développement, le score clinique avait une sensibilité de 68 % et une spécificité de 78 % contre l’ensemble des comparateurs. Avec échographie, les valeurs rapportées étaient de 66 % et 81 %.
Les performances dépendaient du diagnostic concurrent : la spécificité était plus élevée contre les affections d’épaule et plus faible contre la polyarthrite rhumatoïde. Un résultat de classification ne doit donc pas être traité comme un test universel.
L’étude était une cohorte prospective de six mois comprenant 125 patients avec PPR récente et 169 sujets comparateurs. Ces nombres décrivent le travail de développement et non une série suisse de pratique courante.''','p8-classification p8-score-table')+
w(8,'Pourquoi le score ne devient pas une ordonnance','''La classification vise à constituer des groupes comparables pour la recherche. Le diagnostic individuel doit intégrer les maladies concurrentes et les anomalies non capturées par le score.
EULAR 2026 réaffirme cette distinction dans ses principes généraux. Un nombre de points ne justifie donc pas à lui seul une corticothérapie prolongée.
Une personne peut présenter une constellation très évocatrice sans remplir chaque condition de classification ; cette situation demande une synthèse clinique, non l’invention de points supplémentaires.''','p83-eular26-diagnostic p8-classification')+
w(8,'Réponse aux glucocorticoïdes : observation utile, test insuffisant','''Une amélioration rapide est décrite dans les sources historiques et cliniques. Elle est cependant partagée par d’autres affections, dont certaines polyarthrites.
EULAR déconseille un essai diagnostique de glucocorticoïdes : il peut fermer rapidement la fenêtre permettant d’interpréter les examens avant traitement.
La réponse est utilisée pour suivre une maladie correctement évaluée ; elle ne doit pas réparer rétrospectivement une démarche diagnostique insuffisante.''','p8-diagnostic p8-dd-pr p8-eular-no-test')+
prose('''Une CRP et une VS normales rendent la présentation moins habituelle et conduisent à rechercher les autres explications. Les sources cliniques décrivent néanmoins de rares PPR sans augmentation des marqueurs.
Les CK sont habituellement normales, contrairement à ce qui peut être observé dans une myopathie inflammatoire. Une anomalie importante demande une exploration de la cause plutôt qu’une attribution automatique à la PPR.
La conclusion diagnostique indique le degré de cohérence du tableau et les investigations restantes. Elle comporte aussi une décision distincte concernant la présence ou l’absence d’une suspicion d’ACG.''','p8-bio p8-dgn-ck p8-eular-r2'))
